questionvariables.text:
/*Generate data sets*/
/*Generate random standard deviations for the datasets*/
sd_a:rand(50)+1;
sd_b:rand(50)+1;
/* Data Size */
data_num:100;
/*Mean*/
mean_value:200;
/*Generate 100 points with the specified mean and standard deviation*/
data_a: sort(makelist(float(quantile_normal(rand(1.0),mean_value, sd_a)), i, 1, data_num));
data_b: sort(makelist(float(quantile_normal(rand(1.0),mean_value, sd_b)), i, 1, data_num));

/*Variables for histograms*/
/* Number of bars in histogram */
numbars: 30;


/*Options and answer calculation*/
answer_1:if abs(sd_a - sd_b) >= 1 then (if sd_a > sd_b then true else false) else false;
answer_2:if abs(sd_a - sd_b) >= 1 then (if sd_a < sd_b then true else false) else false;
answer_3:if abs(sd_a - sd_b) < 1 then true else false;
ta:[[1,answer_1,"Data set A"],[2,answer_2,"Data set B"],[3,answer_3,"They are virtually the same"]];
